"""Build a self-contained current delivery directly from an explicit source inventory."""
from pathlib import Path
import ast,json,zipfile,datetime,hashlib,subprocess
from models.hope_cad_v5.contract import ROOT,digest,file_sha,CONTRACT
from .common import SOURCE_SCHEMA,source_files,delivery_directory

BOOT = "PHASE='pilot'  # pilot: preflight tích hợp + 4 jobs x256 normals; preflight: chỉ kiểm trước\nSESSION_HOURS=3.0  # soft stop; lưu/resume ở atomic boundary; không phải ETA\nSOURCE_OVERRIDE=None\nRESUME_OVERRIDE=None   # chỉ latest support-v5 pilot output; lần đầu để None\nMVTEC_OVERRIDE=None\nCHECKPOINT_OVERRIDE=None\n\nfrom pathlib import Path,PurePosixPath\nimport hashlib,json,zipfile,os,sys,time,shutil\nSTARTED=time.monotonic()\nINPUT=Path('/kaggle/input');ROOT=Path('/tmp/hope_support_v5_source')\nprint('[BOOTSTRAP] Tìm source HOPE-CAD v5',flush=True)\ndef hash_file(p):\n    with Path(p).open('rb') as stream:return hashlib.file_digest(stream,'sha256').hexdigest()\ndef source_manifest(p):\n    if p.is_dir():return json.loads((p/'bundle_manifest.json').read_text())\n    with zipfile.ZipFile(p) as z:\n        if len(z.namelist())!=len(set(z.namelist())):raise ValueError('Duplicate source ZIP paths')\n        m=json.loads(z.read('bundle_manifest.json'))\n        if set(z.namelist())!=set(m['files'])|{'bundle_manifest.json'}:raise ValueError('Source inventory mismatch')\n        return m\ndef target(name):\n    rel=PurePosixPath(name)\n    if rel.is_absolute() or '..' in rel.parts or rel.as_posix()!=name or '\\\\' in name or ':' in name:raise ValueError('Unsafe source path')\n    p=ROOT/name\n    if not p.resolve().is_relative_to(ROOT.resolve()):raise ValueError('Escaping source path')\n    return p\nif SOURCE_OVERRIDE:choices=[Path(SOURCE_OVERRIDE)]\nelse:\n    choices=[]\n    for p in INPUT.rglob('bundle_manifest.json'):\n        if json.loads(p.read_text()).get('schema')=='hope_support_v5_source_v2':choices.append(p.parent)\n    if not choices:\n        for p in INPUT.rglob('*.zip'):\n            try:\n                if source_manifest(p).get('schema')=='hope_support_v5_source_v2':choices.append(p)\n            except (KeyError,ValueError,zipfile.BadZipFile):pass\nif len(choices)!=1:raise RuntimeError(f'Expected ONE support-v5 source, found {choices}; set SOURCE_OVERRIDE')\nsource=choices[0];manifest=source_manifest(source)\nif manifest['schema']!='hope_support_v5_source_v2':raise ValueError('Wrong source schema')\nif ROOT.exists() and any(ROOT.iterdir()):\n    previous=ROOT/'bundle_manifest.json'\n    if not previous.is_file() or json.loads(previous.read_text()).get('files')!=manifest['files']:\n        raise RuntimeError('Stale source directory: start a fresh kernel/saved version for a different delivery')\n    existing={p.relative_to(ROOT).as_posix() for p in ROOT.rglob('*') if p.is_file() and '__pycache__' not in p.parts}\n    if existing!=set(manifest['files'])|{'bundle_manifest.json'}:\n        raise RuntimeError('Unexpected files in source directory; use a fresh kernel/saved version')\nROOT.mkdir(parents=True,exist_ok=True)\nif source.is_dir():\n    for name,expected in manifest['files'].items():\n        original=source/name;dest=target(name)\n        if not original.is_file() or original.is_symlink() or hash_file(original)!=expected:raise ValueError('Source checksum mismatch: '+name)\n        dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(original,dest)\nelse:\n    with zipfile.ZipFile(source) as z:\n        for name,expected in manifest['files'].items():\n            dest=target(name);dest.parent.mkdir(parents=True,exist_ok=True)\n            with z.open(name) as reader,dest.open('wb') as writer:shutil.copyfileobj(reader,writer)\n            if hash_file(dest)!=expected:raise ValueError('Source checksum mismatch: '+name)\n(ROOT/'bundle_manifest.json').write_text(json.dumps(manifest,sort_keys=True))\nos.chdir(ROOT);sys.path.insert(0,str(ROOT));sys.dont_write_bytecode=True\nos.environ['PYTHONDONTWRITEBYTECODE']='1'\nos.environ['CUBLAS_WORKSPACE_CONFIG']=':4096:8'\nprint('[BOOTSTRAP] Verified source files:',len(manifest['files']),manifest['origin'],flush=True)\nWORK=Path('/kaggle/working/hope_support_v5_pilot')\nASSETS=Path('/tmp/hope_support_v5_assets')\nOUTPUT=Path('/kaggle/working/hope_cad_support_v5_pilot_evidence.zip')\n"
INTRO = "# Nested Learning for CAD — HOPE-CAD v5 normal pilot\n\n**Revision mới, chưa có benchmark gain.** Đọc `architecture_decision_v5.md` và `v5_implementation.md` trong `docs/main_spec/`.\n\nBa inputs: source `hope_cad_support_v5_source_v6_r4.zip`, MVTec AD, ViT-B/8 `vit_base_patch8_224.augreg_in21k.safetensors`. Không cần W6/recovery/W7 evidence hoặc learned weights.\n\nGPU T4 x2; **Save Version → Save & Run All**. Default `PHASE='pilot'`: preflight 24 real normals trên discarded clone, rồi bốn fresh jobs CADIC/GEOMETRIC/FIRST_ORDER/NESTED, mỗi job 256 normal images. Source chỉ extract train/good, không test/GT.\n\n`SESSION_HOURS=3.0` là soft limit để pause/export, không phải ETA. Có heartbeat 30 giây. Resume bằng **latest v5 pilot output** cùng ba inputs, tháo outputs cũ hơn; source/protocol/runtime phải cùng identity. Chỉ muốn preflight riêng: đặt `PHASE='preflight'`, sau PASS attach output đó rồi chạy pilot.\n\n`pilot_complete_pending_review` cần review artifacts. `pilot_complete_scientific_gate_failed` nghĩa chạy xong nhưng mechanism/risk gate không đạt: giữ ZIP/log, không retune hoặc launch anomaly benchmark. Pause không là completion. Hard platform kill có thể ngăn export.\n\nDelivery v6-r4: same method v5, minimized source layout. Do not resume a source-v1 pilot with this source. No new full anomaly benchmark is implemented.\n"
RUN = 'from notebook_support.support_v5.entry import run_notebook\nRESULT=run_notebook(dict(phase=PHASE,session_hours=SESSION_HOURS,started=STARTED,\n    inputs=str(INPUT),work=str(WORK),assets=str(ASSETS),output=str(OUTPUT),\n    RESUME_OVERRIDE=RESUME_OVERRIDE,MVTEC_OVERRIDE=MVTEC_OVERRIDE,CHECKPOINT_OVERRIDE=CHECKPOINT_OVERRIDE))\n'

def build():
    cells=[]
    for i,(kind,text) in enumerate([('markdown',INTRO),('code',BOOT),('code',RUN)]):
        cell=dict(cell_type=kind,id=f'hope-support-v5-{i}',metadata={},source=text.splitlines(True))
        if kind=='code':ast.parse(text);cell.update(outputs=[],execution_count=None)
        cells.append(cell)
    notebook=ROOT/'notebooks/hope_cad_support_v5_kaggle.ipynb'
    notebook.write_text(json.dumps(dict(cells=cells,metadata={'kernelspec':{'display_name':'Python 3','language':'python','name':'python3'}},nbformat=4,nbformat_minor=5),ensure_ascii=False,indent=1)+'\n',encoding='utf-8',newline='\n')
    files=source_files();out=delivery_directory();out.mkdir(parents=True,exist_ok=True)
    def git(*args):
        try:return subprocess.check_output(['git','-C',str(ROOT),*args],stderr=subprocess.DEVNULL,text=True).strip()
        except (OSError,subprocess.CalledProcessError):return None
    origin=dict(branch=git('branch','--show-current'),source_commit=git('rev-parse','HEAD'),merge_parent=git('rev-parse','MERGE_HEAD'),git_dirty=bool(git('status','--porcelain')),delivery_revision='support-v5-v6-r4',created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),identity_basis='all packaged file SHA256s; uncommitted integration is not represented by HEAD alone')
    manifest=dict(schema=SOURCE_SCHEMA,origin=origin,files=files)
    output=out/'hope_cad_support_v5_source_v6_r4.zip';temporary=output.with_suffix('.zip.tmp')
    if output.exists():
        receipt_path=out/'delivery_receipt.json'
        with zipfile.ZipFile(output) as previous:existing=json.loads(previous.read('bundle_manifest.json'))
        if not receipt_path.exists() or existing['files']!=files:raise ValueError('Delivery revision is immutable; create a new delivery revision instead of overwriting source')
        receipt=json.loads(receipt_path.read_text(encoding='utf-8'))
        if file_sha(output)!=receipt['sha256']:raise ValueError('Existing delivery was corrupted')
        print(json.dumps(receipt,indent=2));return receipt
    with zipfile.ZipFile(temporary,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for name in files:z.write(ROOT/name,name)
        z.writestr('bundle_manifest.json',json.dumps(manifest,sort_keys=True))
    with zipfile.ZipFile(temporary) as z:
        for name,expected in files.items():
            with z.open(name) as stream:
                if hashlib.file_digest(stream,'sha256').hexdigest()!=expected:raise ValueError('source copy mismatch '+name)
    temporary.replace(output)
    receipt=dict(schema='hope_support_v6_delivery_receipt',source_zip=str(output),sha256=file_sha(output),bytes=output.stat().st_size,files=len(files),source_digest=digest(files),design_digest=digest(CONTRACT),old_source_v1_resume_compatible=False,method_equations_unchanged=True,real_pilot_pending=True)
    (out/'delivery_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8');print(json.dumps(receipt,indent=2));return receipt
if __name__=='__main__':build()
